```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, count(*) AS n, round(avg(value),2) AS avg_value FROM abnormal_metrics WHERE service_name='rate' AND metric='k8s.deployment.available' GROUP BY ALL",
          "claim": "Rate deployment reports 0 available replicas across the whole abnormal window, while desired stays at 1."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, attr_k8s_pod_name pod, metric, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'rate%' GROUP BY ALL UNION ALL SELECT 'norm', attr_k8s_pod_name, metric, min(value), max(value) FROM normal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'rate%' GROUP BY ALL",
          "claim": "Rate pod restart counter rises to 2-6 in the incident period, versus 0 in normal operation."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='rate' GROUP BY ALL UNION ALL SELECT 'normal_rate', span_name, attr_span_kind, count(*) FROM normal_traces WHERE service_name='rate' GROUP BY ALL",
          "claim": "Rate emits no spans at all in the abnormal period, while normal period has about 1058 spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "Search's calls to rate.GetRates fail 1006 of 1014 times, each returning in about 0.02 ms, a fast refusal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY ALL",
          "claim": "Search's rate.GetRates client spans fail and its search.Search/Nearby server spans error in the same 1006 requests."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY ALL",
          "claim": "Search logs 'Failed to get rates from rate service' hundreds of times during the incident."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL",
          "claim": "Frontend /hotels returns 500 errors on 741 requests, failing on search.Search/Nearby; normal /hotels succeeds at about 7 ms."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 'Search service failed' hundreds of times, surfacing the search failure to users."
        }
      ]
    }
  ]
}
```

